    description: "Комплект молдингов для Тойота Креста jzx100 (без обвеса)\nМолдинг изготавливается по технологии FDM. Изделие идет под покраску, вы можете подобрать цвет под ваш автомобиль самостоятельно.Накладки на дверь крепятся к машине на двусторонний скотч как предусмотрено производителем.\nОсобенности:\n· Прочный пластик, устойчив к механическим повреждениям и погодным условиям. Изготовление по технологии FDM.\n· Защита нижней части дверей и кузова от сколов и повреждений.\n· Простая установка на скотч «3М» (идет в комплекте).\n· Деталь имеет шероховатую текстуру\nУстановка:\nОчистить поверхность машины средством для удаления жиров и масел. Дождаться, когда поверхность полностью высохнет. Для лучшей сцепки можно нанести праймер (приобретается отдельно).Удалить защитный слой скотча и плотно приложить к машине, предварительно примерив. Желательно дать накладкам отстояться около суток, чтобы хорошо приклеилис…",
